/* Motion utilities - duration utilities are data-driven from canonical motion tokens; the ring-safe transitions and the presence bridge below are static. */

@utility duration-0 {
  --tw-duration: var(--nx-motion-duration-0);
  transition-duration: var(--nx-motion-duration-0);
}

@utility duration-faster {
