}

@utility duration-slower {
  --tw-duration: var(--nx-motion-duration-slower);
  transition-duration: var(--nx-motion-duration-slower);
}

@utility transition-control {
  transition-property: color, background-color, border-color;
  transition-timing-function: var(
    --tw-ease,
    --theme(--default-transition-timing-function)
  );
  transition-duration: var(
    --tw-duration,
    --theme(--default-transition-duration)
  );
}

@utility transition-field {
  transition-property: color, background-color;
  transition-timing-function: var(
    --tw-ease,
    --theme(--default-transition-timing-function)
  );
  transition-duration: var(
    --tw-duration,
    --theme(--default-transition-duration)
  );
}

@keyframes nx-overlay-presence-exit {
  from {
    --nx-overlay-presence-phase: 0;
  }
  to {
    --nx-overlay-presence-phase: 1;
  }
}

@utility animate-overlay-presence-exit {
  animation-name: nx-overlay-presence-exit;
  animation-duration: var(--tw-duration, var(--nx-motion-duration-fast));
  animation-timing-function: linear;
}

