'use client';

import type {
  NxdsAppearanceCookieOptions,
  NxdsAppearanceState,
} from '@nxds/core';

import {
  NxdsAppearanceProvider,
  type NxdsAppearanceProviderProps,
} from './provider';

export interface CreateNxdsAppearanceOptions {
  storageKey?: string | false;
  cookieWriteKey?: string | false;
  cookieOptions?: NxdsAppearanceCookieOptions;
  defaultState?: NxdsAppearanceState;
}

type ConfiguredProviderProps = Omit<
  NxdsAppearanceProviderProps,
  'storageKey' | 'cookieWriteKey' | 'cookieOptions' | 'defaultState'
>;

export function createNxdsAppearance({
  storageKey,
  cookieWriteKey,
  cookieOptions,
  defaultState,
}: CreateNxdsAppearanceOptions = {}) {
  function ConfiguredNxdsAppearanceProvider({
    children,
    ...props
  }: ConfiguredProviderProps) {
    return (
      <NxdsAppearanceProvider
        {...props}
        storageKey={storageKey}
        cookieWriteKey={cookieWriteKey}
        cookieOptions={cookieOptions}
        defaultState={defaultState}
      >
        {children}
      </NxdsAppearanceProvider>
    );
  }

  return {
    NxdsAppearanceProvider: ConfiguredNxdsAppearanceProvider,
  };
}

'use client';

// Client runtime Appearance surface. Server-safe script helpers are exported from ./server.
export type { CreateNxdsAppearanceOptions } from './factory';
export { createNxdsAppearance } from './factory';
export type {
  NxdsAppearanceContextValue,
  NxdsAppearanceProviderProps,
} from './provider';
export { NxdsAppearanceProvider, useNxdsAppearance } from './provider';

'use client';

import {
  createContext,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
} from 'react';

import {
  applyNxdsAppearance,
  DEFAULT_NXDS_APPEARANCE,
  DEFAULT_STORAGE_KEY,
  type NxdsAppearanceCookieOptions,
  type NxdsAppearanceState,
  type NxdsResolvedAppearanceMode,
  persistNxdsAppearance,
  prefersDarkColorScheme,
  readStoredNxdsAppearance,
  removeNxdsAppearance,
  resolveNxdsAppearanceMode,
  sanitizeNxdsAppearance,
  watchColorScheme,
} from '@nxds/core';

export interface NxdsAppearanceContextValue {
  state: NxdsAppearanceState;
  setState: Dispatch<SetStateAction<NxdsAppearanceState>>;
  resolvedMode: NxdsResolvedAppearanceMode;
  mounted: boolean;
  reset: () => void;
}

export interface NxdsAppearanceProviderProps {
  children: ReactNode;
  state?: NxdsAppearanceState;
  defaultState?: NxdsAppearanceState;
  onStateChange?: (state: NxdsAppearanceState) => void;
  /**
   * localStorage key for the saved appearance. The head script reads it before first paint and the provider after mount, overriding `defaultState`.
   * Pass `false` to turn it off.
   */
  storageKey?: string | false;
  /**
   * Cookie the provider writes so your server can render the saved appearance.
   * The client never reads it.
   */
  cookieWriteKey?: string | false;
  cookieOptions?: NxdsAppearanceCookieOptions;
}

const NxdsAppearanceContext = createContext<NxdsAppearanceContextValue | null>(
  null
);

const canUseDOM = (): boolean =>
  typeof window !== 'undefined' && typeof document !== 'undefined';

function subscribeToNothing() {
  return () => {};
}

function nextAppearanceState(
  update: SetStateAction<NxdsAppearanceState>,
  previous: NxdsAppearanceState
): NxdsAppearanceState {
  return sanitizeNxdsAppearance(
    typeof update === 'function' ? update(previous) : update
  );
}

export function NxdsAppearanceProvider({
  children,
  state,
  defaultState,
  onStateChange,
  storageKey = DEFAULT_STORAGE_KEY,
  cookieWriteKey = false,
  cookieOptions,
}: NxdsAppearanceProviderProps) {
  const isControlled = state !== undefined;
  const initialState = useMemo(
    () => sanitizeNxdsAppearance(defaultState ?? DEFAULT_NXDS_APPEARANCE),
    [defaultState]
  );
  const mounted = useSyncExternalStore(
    subscribeToNothing,
    () => true,
    () => false
  );
  // The saved appearance, read once after hydration so the server and first client render agree.
  const stored = useMemo(
    () =>
      mounted
        ? readStoredNxdsAppearance(storageKey, initialState)
        : initialState,
    [initialState, mounted, storageKey]
  );
  /** The appearance picked in this session, which wins over the saved one. */
  const [chosen, setChosen] = useState<NxdsAppearanceState | null>(null);
  const chosenRef = useRef<NxdsAppearanceState | null>(null);
  const activeState = state ?? chosen ?? stored;
  const systemDark = useSyncExternalStore(
    watchColorScheme,
    prefersDarkColorScheme,
    () => false
  );
  const resolvedMode = resolveNxdsAppearanceMode(activeState.mode, systemDark);

  const setState = useCallback<Dispatch<SetStateAction<NxdsAppearanceState>>>(
    (update) => {
      if (isControlled) {
        onStateChange?.(nextAppearanceState(update, activeState));
        return;
      }
      const next = nextAppearanceState(update, chosenRef.current ?? stored);
      chosenRef.current = next;
      setChosen(next);
      onStateChange?.(next);
    },
    [activeState, isControlled, onStateChange, stored]
  );

  const reset = useCallback(() => {
    setState(initialState);
  }, [initialState, setState]);

  useEffect(() => {
    if (!mounted || isControlled) return;

    persistNxdsAppearance(activeState, {
      storageKey,
      cookieWriteKey,
      cookieOptions,
    });
  }, [
    activeState,
    cookieWriteKey,
    cookieOptions,
    isControlled,
    mounted,
    storageKey,
  ]);

  useEffect(() => {
    if (!mounted) return;

    applyNxdsAppearance(activeState, systemDark);
  }, [activeState, mounted, systemDark]);

  useEffect(() => {
    if (!canUseDOM()) return;

    return removeNxdsAppearance;
  }, []);

  const value = useMemo<NxdsAppearanceContextValue>(
    () => ({ state: activeState, setState, resolvedMode, mounted, reset }),
    [activeState, mounted, reset, resolvedMode, setState]
  );

  return (
    <NxdsAppearanceContext.Provider value={value}>
      {children}
    </NxdsAppearanceContext.Provider>
  );
}

export function useNxdsAppearance(): NxdsAppearanceContextValue {
  const context = useContext(NxdsAppearanceContext);

  if (!context) {
    throw new Error(
      'useNxdsAppearance must be used within <NxdsAppearanceProvider>'
    );
  }

  return context;
}

import {
  createDefaultNxdsAppearanceSnapshot,
  createNxdsAppearanceBootstrapScript,
  createNxdsAppearanceSnapshotFromState,
  type NxdsAppearanceState,
  sanitizeNxdsAppearance,
} from '@nxds/core';

export interface NxdsAppearanceScriptProps {
  storageKey?: string | false;
  defaultState?: NxdsAppearanceState;
  nonce?: string;
}

export interface CreateNxdsAppearanceScriptOptions {
  storageKey?: string | false;
  defaultState?: NxdsAppearanceState;
}

function defaultSnapshotFor(defaultState: NxdsAppearanceState | undefined) {
  return defaultState
    ? createNxdsAppearanceSnapshotFromState(
        sanitizeNxdsAppearance(defaultState)
      )
    : createDefaultNxdsAppearanceSnapshot();
}

export function NxdsAppearanceScript({
  storageKey,
  defaultState,
  nonce,
}: NxdsAppearanceScriptProps) {
  return (
    <script
      data-nxds-appearance-script=""
      nonce={nonce}
      dangerouslySetInnerHTML={{
        __html: createNxdsAppearanceBootstrapScript({
          storageKey,
          defaultSnapshot: defaultSnapshotFor(defaultState),
        }),
      }}
    />
  );
}

export function createNxdsAppearanceScript({
  storageKey,
  defaultState,
}: CreateNxdsAppearanceScriptOptions = {}) {
  function ConfiguredNxdsAppearanceScript({
    nonce,
  }: Pick<NxdsAppearanceScriptProps, 'nonce'>) {
    return (
      <NxdsAppearanceScript
        nonce={nonce}
        storageKey={storageKey}
        defaultState={defaultState}
      />
    );
  }

  return ConfiguredNxdsAppearanceScript;
}

export type {
  CreateNxdsAppearanceScriptOptions,
  NxdsAppearanceScriptProps,
} from './script';
export { createNxdsAppearanceScript, NxdsAppearanceScript } from './script';

