function AlertIcon({ className, ...props }: AlertIconProps) {
  return (
    <span
      data-slot="alert-icon"
      aria-hidden="true"
      className={cn(
        'nx:flex nx:[&>svg]:size-4',
        'nx:group-data-[layout=stack]/alert:translate-y-0.5',
        className
