    return (
      <Slot {...sharedProps} {...props} tabIndex={isDisabled ? -1 : tabIndex}>
        {children}
      </Slot>
    );

  return (
    <button
      {...sharedProps}
      {...props}
      type={type}
      disabled={isDisabled}
      tabIndex={tabIndex}
    >
      <ButtonContent loading={loading} startIcon={startIcon} endIcon={endIcon}>
        {children}
      </ButtonContent>
    </button>
  );
