'use client';

import * as React from 'react';

import useEmblaCarousel, {
  type UseEmblaCarouselType,
} from 'embla-carousel-react';

import { IconArrowLeft, IconArrowRight } from '../../lib/icons';
import { cn } from '../../lib/utils';
import { Button } from '../button/button';

type CarouselApi = UseEmblaCarouselType[1];
type UseCarouselParameters = Parameters<typeof useEmblaCarousel>;
type CarouselOptions = UseCarouselParameters[0];
type CarouselPlugin = UseCarouselParameters[1];

/**
 * Props for Carousel. Install the optional `embla-carousel-react` peer dependency in your app.
 */
type CarouselProps = {
  /** Embla options, such as `loop`, `align` or `dragFree`. */
  opts?: CarouselOptions;
  /** Embla plugins, such as autoplay or wheel gestures. */
  plugins?: CarouselPlugin;
  /**
   * Scroll axis.
   */
  orientation?: 'horizontal' | 'vertical';
  /** Receives the Embla API after setup, for external control. */
  setApi?: (api: CarouselApi) => void;
};

type CarouselContextProps = {
  carouselRef: ReturnType<typeof useEmblaCarousel>[0];
  orientation: NonNullable<CarouselProps['orientation']>;
  scrollPrev: () => void;
  scrollNext: () => void;
  canScrollPrev: boolean;
  canScrollNext: boolean;
};

const carouselControlClasses =
  'nx:absolute nx:rounded-full nx:after:absolute nx:after:-inset-2';

const CarouselContext = React.createContext<CarouselContextProps | null>(null);

function useCarousel() {
  const context = React.useContext(CarouselContext);

  if (!context) {
    throw new Error('useCarousel must be used within a <Carousel />');
  }

  return context;
}

/**
 * Slideshow built on Embla that scrolls horizontally or vertically.
 * Put `CarouselItem`s in `CarouselContent`, and add `CarouselPrevious` and `CarouselNext`.
 * Arrow keys along the scroll axis move between slides.
 *
 * The Previous and Next buttons sit outside the frame. Leave horizontal room, such as padding, so they don't clip on narrow screens.
 */
function Carousel({
  orientation = 'horizontal',
  opts,
  setApi,
  plugins,
  className,
  children,
  ...props
}: React.ComponentProps<'div'> & CarouselProps) {
  const [carouselRef, api] = useEmblaCarousel(
    {
      ...opts,
      axis: orientation === 'horizontal' ? 'x' : 'y',
    },
    plugins
  );
  // Read the prev/next affordances from Embla's scroll position (external system).
  const subscribe = React.useCallback(
    (onChange: () => void) => {
      if (!api) return () => {};
      api.on('reInit', onChange);
      api.on('select', onChange);
      return () => {
        api.off('reInit', onChange);
        api.off('select', onChange);
      };
    },
    [api]
  );
  const canScrollPrev = React.useSyncExternalStore(
    subscribe,
    () => api?.canScrollPrev() ?? false,
    () => false
  );
  const canScrollNext = React.useSyncExternalStore(
    subscribe,
    () => api?.canScrollNext() ?? false,
    () => false
  );

  const scrollPrev = React.useCallback(() => api?.scrollPrev(), [api]);
  const scrollNext = React.useCallback(() => api?.scrollNext(), [api]);

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    const isPrev =
      event.key === (orientation === 'horizontal' ? 'ArrowLeft' : 'ArrowUp');
    const isNext =
      event.key === (orientation === 'horizontal' ? 'ArrowRight' : 'ArrowDown');
    if (!isPrev && !isNext) return;
    // Don't hijack arrow keys from a focused control that uses them itself.
    if (
      (event.target as HTMLElement).closest(
        'input, textarea, select, [contenteditable="true"]'
      )
    ) {
      return;
    }

    if (isPrev && !canScrollPrev) return;
    if (isNext && !canScrollNext) return;

    event.preventDefault();
    if (isPrev) scrollPrev();
    else scrollNext();
  };

  // Hand the Embla API to the consumer once it initialises.
  React.useEffect(() => {
    if (!api || !setApi) return;
    setApi(api);
  }, [api, setApi]);

  const contextValue = React.useMemo(
    () => ({
      carouselRef,
      orientation,
      scrollPrev,
      scrollNext,
      canScrollPrev,
      canScrollNext,
    }),
    [
      carouselRef,
      orientation,
      scrollPrev,
      scrollNext,
      canScrollPrev,
      canScrollNext,
    ]
  );

  return (
    <CarouselContext.Provider value={contextValue}>
      <div
        onKeyDownCapture={handleKeyDown}
        className={cn('nx:relative', className)}
        role="region"
        aria-roledescription="carousel"
        data-slot="carousel"
        data-orientation={orientation}
        {...props}
      >
        {children}
      </div>
    </CarouselContext.Provider>
  );
}

function CarouselContent({ className, ...props }: React.ComponentProps<'div'>) {
  const { carouselRef, orientation } = useCarousel();

  return (
    <div
      ref={carouselRef}
      className="nx:overflow-hidden"
      data-slot="carousel-content"
    >
      <div
        className={cn(
          'nx:flex',
          orientation === 'horizontal' ? 'nx:-ml-4' : 'nx:-mt-4 nx:flex-col',
          className
        )}
        {...props}
      />
    </div>
  );
}

function CarouselItem({ className, ...props }: React.ComponentProps<'div'>) {
  const { orientation } = useCarousel();

  return (
    <div
      role="group"
      aria-roledescription="slide"
      data-slot="carousel-item"
      className={cn(
        'nx:min-w-0 nx:shrink-0 nx:grow-0 nx:basis-full',
        orientation === 'horizontal' ? 'nx:pl-4' : 'nx:pt-4',
        className
      )}
      {...props}
    />
  );
}

function CarouselPrevious({
  className,
  variant = 'outline',
  size = 'icon',
  ...props
}: React.ComponentProps<typeof Button>) {
  const { orientation, scrollPrev, canScrollPrev } = useCarousel();

  return (
    <Button
      data-slot="carousel-previous"
      variant={variant}
      size={size}
      className={cn(
        carouselControlClasses,
        orientation === 'horizontal'
          ? 'nx:top-1/2 nx:-left-12 nx:-translate-y-1/2'
          : 'nx:-top-12 nx:left-1/2 nx:-translate-x-1/2 nx:rotate-90',
        className
      )}
      disabled={!canScrollPrev}
      onClick={scrollPrev}
      {...props}
    >
      <IconArrowLeft />
      <span className="nx:sr-only">Previous slide</span>
    </Button>
  );
}

function CarouselNext({
  className,
  variant = 'outline',
  size = 'icon',
  ...props
}: React.ComponentProps<typeof Button>) {
  const { orientation, scrollNext, canScrollNext } = useCarousel();

  return (
    <Button
      data-slot="carousel-next"
      variant={variant}
      size={size}
      className={cn(
        carouselControlClasses,
        orientation === 'horizontal'
          ? 'nx:top-1/2 nx:-right-12 nx:-translate-y-1/2'
          : 'nx:-bottom-12 nx:left-1/2 nx:-translate-x-1/2 nx:rotate-90',
        className
      )}
      disabled={!canScrollNext}
      onClick={scrollNext}
      {...props}
    >
      <IconArrowRight />
      <span className="nx:sr-only">Next slide</span>
    </Button>
  );
}

export {
  Carousel,
  type CarouselApi,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
  type CarouselProps,
};

'use client';

import * as React from 'react';

import * as RechartsPrimitive from 'recharts';

import { cn } from '../../lib/utils';

/**
 * Label, icon and color for each series, keyed by the series `dataKey`.
 * Each `color` becomes a `--color-{key}` variable, so a series can use `fill="var(--color-{key})"`.
 * Keys with a `color` may use only letters, numbers, `_` and `-`.
 *
 * Set `color` to a chart token, such as `var(--nx-color-chart-categorical-1)`, so it follows light and dark mode.
 * Treat `color` as trusted CSS, not user data.
 */
export type ChartConfig = {
  [key: string]: {
    label?: React.ReactNode;
    /** @thirdPartyShape Recharts' legend and tooltip render it as a component. */
    icon?: React.ComponentType;
    color?: string;
  };
};

type ChartContextProps = {
  config: ChartConfig;
};

const ChartContext = React.createContext<ChartContextProps | null>(null);
const chartColorKeyPattern = /^[A-Za-z0-9_-]+$/;

type ChartRootStyle = React.CSSProperties & {
  [key: `--color-${string}`]: string | undefined;
};

function useChart() {
  const context = React.useContext(ChartContext);
  if (!context) {
    throw new Error('useChart must be used within a <ChartContainer />');
  }
  return context;
}

function ChartContainer({
  id,
  className,
  children,
  config,
  style,
  ...props
}: React.ComponentProps<'div'> & {
  config: ChartConfig;
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >['children'];
}) {
  const uniqueId = React.useId();
  // Strip the colons React emits in some runtimes (`:r0:`) so the data attribute
  // remains convenient to query in tests and consumer CSS.
  const chartId = `chart-${id || uniqueId.replace(/:/g, '')}`;
  const chartStyle = getChartStyle(config, style);

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "nx:flex nx:aspect-video nx:justify-center nx:typography-body-small nx:[&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground nx:[&_.recharts-cartesian-axis-tick_text]:tabular-nums nx:[&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border-default nx:[&_.recharts-curve.recharts-tooltip-cursor]:stroke-border-default nx:[&_.recharts-dot[stroke='#fff']]:stroke-transparent nx:[&_.recharts-layer]:outline-hidden nx:[&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border-default nx:[&_.recharts-radial-bar-background-sector]:fill-muted nx:[&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted nx:[&_.recharts-reference-line_[stroke='#ccc']]:stroke-border-default nx:[&_.recharts-sector]:outline-hidden nx:[&_.recharts-sector[stroke='#fff']]:stroke-transparent nx:[&_.recharts-surface]:outline-hidden",
          className
        )}
        style={chartStyle}
        {...props}
      >
        <RechartsPrimitive.ResponsiveContainer>
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

function getChartStyle(
  config: ChartConfig,
  style: React.CSSProperties | undefined
) {
  const colorStyle = Object.entries(config).reduce<ChartRootStyle>(
    (acc, [key, conf]) => {
      if (!conf.color || !chartColorKeyPattern.test(key)) {
        return acc;
      }

      acc[`--color-${key}`] = conf.color;

      return acc;
    },
    {}
  );

  if (!Object.keys(colorStyle).length) {
    return style;
  }

  return { ...colorStyle, ...style };
}

const ChartTooltip = RechartsPrimitive.Tooltip;

type ChartIndicator = 'line' | 'dot' | 'dashed';

export type ChartTooltipFormatter = (
  value: RechartsPrimitive.TooltipPayloadEntry['value'],
  name: RechartsPrimitive.TooltipPayloadEntry['name'],
  item: RechartsPrimitive.TooltipPayloadEntry,
  index: number,
  payload: RechartsPrimitive.TooltipPayloadEntry['payload']
) => React.ReactNode;

interface ChartTooltipContentProps extends Pick<
  RechartsPrimitive.DefaultTooltipContentProps,
  'payload' | 'label' | 'labelFormatter' | 'labelClassName'
> {
  active?: boolean;
  className?: string;
  indicator?: ChartIndicator;
  hideLabel?: boolean;
  hideIndicator?: boolean;
  formatter?: ChartTooltipFormatter;
  color?: string;
  nameKey?: string;
  labelKey?: string;
}

/** Shared class for one tooltip row (formatter row and default row alike). */
const tooltipRowClassName = (indicator: ChartIndicator) =>
  cn(
    'nx:[&>svg]:text-muted-foreground nx:flex nx:w-full nx:flex-wrap nx:items-stretch nx:gap-2 nx:[&>svg]:h-2.5 nx:[&>svg]:w-2.5',
    indicator === 'dot' && 'nx:items-center'
  );

interface ChartTooltipLabelProps {
  payload: ReadonlyArray<RechartsPrimitive.TooltipPayloadEntry>;
  label?: React.ReactNode;
  labelKey?: string;
  labelFormatter?: ChartTooltipContentProps['labelFormatter'];
  labelClassName?: string;
}

/** The tooltip's leading label, resolved from config / `labelKey` / `labelFormatter`. */
function ChartTooltipLabel({
  payload,
  label,
  labelKey,
  labelFormatter,
  labelClassName,
}: ChartTooltipLabelProps) {
  const { config } = useChart();
  const [item] = payload;
  const key = `${labelKey || item?.dataKey || item?.name || 'value'}`;
  const itemConfig = getPayloadConfigFromPayload(config, item, key);
  const value =
    !labelKey && typeof label === 'string'
      ? config[label]?.label || label
      : itemConfig?.label;

  if (labelFormatter) {
    return (
      <div className={cn('nx:typography-label-default', labelClassName)}>
        {labelFormatter(value, payload)}
      </div>
    );
  }
  if (!value) return null;
  return (
    <div className={cn('nx:typography-label-default', labelClassName)}>
      {value}
    </div>
  );
}

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = 'dot',
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  color,
  nameKey,
  labelKey,
}: ChartTooltipContentProps) {
  if (!active || !payload?.length) return null;

  const nestLabel = payload.length === 1 && indicator !== 'dot';
  const tooltipLabel = hideLabel ? null : (
    <ChartTooltipLabel
      payload={payload}
      label={label}
      labelKey={labelKey}
      labelFormatter={labelFormatter}
      labelClassName={labelClassName}
    />
  );

  return (
    <div
      className={cn(
        'nx:border-border-default nx:bg-popover nx:text-popover-foreground nx:grid nx:min-w-32 nx:items-start nx:gap-1.5 nx:rounded-md nx:border-default nx:px-3 nx:py-1.5 nx:typography-body-small nx:shadow-lg',
        className
      )}
    >
      {!nestLabel ? tooltipLabel : null}
      <div className="nx:grid nx:gap-1.5">
        {payload.map((item, index) =>
          formatter && item.value !== undefined && item.name ? (
            <div
              key={`${item.dataKey}`}
              className={tooltipRowClassName(indicator)}
            >
              {formatter(item.value, item.name, item, index, item.payload)}
            </div>
          ) : (
            <ChartTooltipItem
              key={`${item.dataKey}`}
              item={item}
              indicator={indicator}
              hideIndicator={hideIndicator}
              color={color}
              nameKey={nameKey}
              nestLabel={nestLabel}
            >
              {nestLabel ? tooltipLabel : null}
            </ChartTooltipItem>
          )
        )}
      </div>
    </div>
  );
}

interface ChartTooltipIndicatorProps {
  itemConfig: ChartConfig[string] | undefined;
  hideIndicator: boolean;
  indicator: ChartIndicator;
  nestLabel: boolean;
  color: string | undefined;
}

/** The leading swatch for a tooltip row: a config icon, or the dot/line/dashed mark. */
function ChartTooltipIndicator({
  itemConfig,
  hideIndicator,
  indicator,
  nestLabel,
  color,
}: ChartTooltipIndicatorProps) {
  if (itemConfig?.icon) {
    const Icon = itemConfig.icon;
    return <Icon />;
  }
  if (hideIndicator) return null;

  return (
    <div
      className={cn(
        'nx:shrink-0 nx:rounded-[2px] nx:border-(--color-border) nx:bg-(--color-bg)',
        {
          'nx:h-2.5 nx:w-2.5': indicator === 'dot',
