  return errorMessages[code];
}

function nodeIds(node: FilterGroup | FilterRule): string[] {
  if (node.kind === 'rule') return [node.id];
  return [node.id, ...node.children.flatMap(nodeIds)];
}

// Restored trees can already hold IDs from an earlier page load, so skip any in use.
let nodeCount = 0;
function createNodeId(prefix: string, taken: ReadonlySet<string>) {
  let id: string;
  do {
    nodeCount += 1;
    id = `${prefix}${nodeCount}`;
  } while (taken.has(id));
  return id;
}

interface PickerProps<Value extends string> {
  className?: string;
  leading?: React.ReactNode;
  label: string;
  value: Value;
  options: readonly { value: Value; label: string }[];
  onValueChange: (value: Value) => void;
  disabled?: boolean;
  invalid?: boolean;
  describedBy?: string;
  triggerRef?: React.Ref<HTMLButtonElement>;
}
function Picker<Value extends string>({
  label,
  value,
  options,
  onValueChange,
  disabled,
  invalid,
  describedBy,
  triggerRef,
  className,
  leading,
}: PickerProps<Value>) {
  const available = options.some((option) => option.value === value);
  function select(next: string) {
    const option = options.find((item) => item.value === next);
    if (option) onValueChange(option.value);
  }
  return (
    <Select value={value} onValueChange={select} disabled={disabled}>
      <SelectTrigger
        ref={triggerRef}
        aria-label={label}
        aria-invalid={invalid}
        aria-describedby={describedBy}
        className={cn(
          'nx:h-(--nx-spacing-8) nx:w-auto nx:min-w-0 nx:max-w-full nx:px-2.5 nx:[&>span]:flex-1 nx:[&>span]:text-start',
          className
        )}
      >
        {leading}
        <SelectValue placeholder="Choose…">
          {!available && value ? 'Unavailable selection' : undefined}
        </SelectValue>
      </SelectTrigger>
      <SelectContent className="nx:max-w-(--radix-select-content-available-width)">
        {options
          .filter((option) => option.value !== '')
          .map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
      </SelectContent>
    </Select>
  );
}
function MultipleValues({
  field,
  value,
