              className="nx:not-has-[:disabled]:hover:bg-popover-hover"
            >
              <Checkbox
                id={`${id}-${index}`}
                checked={value.includes(option.value)}
                disabled={disabled}
                onCheckedChange={() => toggle(option.value)}
              />
              <span className="nx:min-w-0 nx:break-words">{option.label}</span>
            </ChoiceRow>
          ))}
          {!options.length && (
            <p className="nx:m-0 nx:p-2 nx:typography-body-small nx:text-muted-foreground">
              No options found.
            </p>
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}
function RuleValue({
  field,
  rule,
  onValueChange,
  disabled,
  errorId,
  invalid,
}: {
  field: FilterField;
  rule: FilterRule;
  onValueChange: (rule: FilterRule) => void;
  disabled?: boolean;
  errorId?: string;
  invalid: boolean;
}) {
  if (rule.operator === 'isEmpty' || rule.operator === 'isNotEmpty')
    return (
      <span className="nx:self-center nx:typography-body-small nx:text-muted-foreground">
        No value needed
      </span>
    );
  if (rule.operator === 'isAnyOf' || rule.operator === 'isNoneOf') {
    if (field.type !== 'choice') return null;
    return (
      <MultipleValues
        field={field}
        value={rule.value}
        onValueChange={(value) => onValueChange({ ...rule, value })}
        disabled={disabled}
        invalid={invalid}
        describedBy={errorId}
      />
    );
  }
  if (rule.operator === 'between') {
    if (field.type === 'choice') return null;
    const [start, end] = rule.value;
    const changeStart = (event: React.ChangeEvent<HTMLInputElement>) =>
      onValueChange({ ...rule, value: [event.target.value, end] });
    const changeEnd = (event: React.ChangeEvent<HTMLInputElement>) =>
      onValueChange({ ...rule, value: [start, event.target.value] });
    return (
      <div className="nx:flex nx:min-w-0 nx:max-w-full nx:flex-wrap nx:items-center nx:gap-2 nx:@lg/rule:flex-nowrap nx:@lg/rule:gap-0 nx:@lg/rule:[&>input]:flex-1 nx:@lg/rule:[&>input:first-child]:rounded-e-none">
        <Input
          size="sm"
          type={field.type}
          step={field.type === 'number' ? 'any' : undefined}
          aria-label={`${field.label} start`}
          placeholder="From"
          value={start}
          onChange={changeStart}
          disabled={disabled}
          aria-invalid={invalid}
          aria-describedby={errorId}
          className="nx:min-w-0 nx:w-36 nx:max-w-full nx:typography-body-default nx:h-(--nx-spacing-8)"
        />
        <Input
          size="sm"
          type={field.type}
          step={field.type === 'number' ? 'any' : undefined}
          aria-label={`${field.label} end`}
          placeholder="To"
          value={end}
          onChange={changeEnd}
          disabled={disabled}
          aria-invalid={invalid}
          aria-describedby={errorId}
          className="nx:min-w-0 nx:w-36 nx:max-w-full nx:typography-body-default nx:h-(--nx-spacing-8)"
        />
      </div>
    );
  }
  if (field.type === 'choice')
    return (
      <Picker
        className="nx:w-full nx:bg-container"
        label={`${field.label} value`}
        options={field.options}
        value={rule.value}
        onValueChange={(value) => onValueChange({ ...rule, value })}
        disabled={disabled}
        invalid={invalid}
        describedBy={errorId}
      />
    );
  return (
    <Input
      size="sm"
      type={field.type}
      step={field.type === 'number' ? 'any' : undefined}
      aria-label={`${field.label} value`}
      placeholder={field.type === 'date' ? undefined : 'Enter a value…'}
      value={rule.value}
      onChange={(event) =>
        onValueChange({ ...rule, value: event.target.value })
      }
      disabled={disabled}
      aria-invalid={invalid}
      aria-describedby={errorId}
      className="nx:min-w-0 nx:w-full nx:max-w-full nx:bg-container nx:typography-body-default nx:h-(--nx-spacing-8)"
    />
  );
}
