 * @experimental Inferred from Atlassian's `<Show>` / `<Hide>`; the API may change before stable.
 */
function Hide({
  as: Comp = 'span',
  className,
  children,
  above,
  below,
  containerAbove,
  containerBelow,
  ...props
}: ResponsiveVisibilityProps) {
  return (
    <Comp
      data-slot="hide"
      className={cn(
        className,
        visibilityClassName(
