import { IconArrowDown, IconArrowUp } from '../../lib/icons';
import { cn } from '../../lib/utils';
import { Button } from '../button/button';
import { ScrollBar } from '../scroll-area/scroll-area';

/** Slack a scroll position gets before it stops counting as "at the edge". */
const EDGE_THRESHOLD = 24;

interface MessageScrollerContextValue {
  isScrollable: boolean;
  isAtEnd: boolean;
  isAtStart: boolean;
  scrollToEnd: () => void;
  scrollToStart: () => void;
}

interface MessageScrollerNodesContextValue {
  setViewport: (node: HTMLDivElement | null) => void;
  setContent: (node: HTMLDivElement | null) => void;
}

const MessageScrollerContext =
  React.createContext<MessageScrollerContextValue | null>(null);

const MessageScrollerNodesContext =
  React.createContext<MessageScrollerNodesContextValue | null>(null);

/**
 * Reads or changes the scroll position from anywhere inside a
 * `MessageScrollerProvider`. Works outside the scroller too, such as in a
 * composer's send button.
 */
function useMessageScroller() {
  const context = React.useContext(MessageScrollerContext);

  if (!context) {
    throw new Error(
      'useMessageScroller must be used within a <MessageScrollerProvider />'
    );
  }

  return context;
}

function useMessageScrollerNodes() {
  const context = React.useContext(MessageScrollerNodesContext);

  if (!context) {
    throw new Error(
      'MessageScroller parts must be used within a <MessageScrollerProvider />'
    );
  }

  return context;
}

// Inline, so `reduceMotion`'s `scroll-behavior: auto !important` still wins.
function smoothScrollTo(viewport: HTMLElement, top: number) {
  const previous = viewport.style.scrollBehavior;
  viewport.style.scrollBehavior = 'smooth';
  viewport.scrollTo({ top });
  viewport.style.scrollBehavior = previous;
}

/**
 * Props for the MessageScrollerProvider component.
 */
interface MessageScrollerProviderProps {
  children?: React.ReactNode;
}

/**
 * Holds the scroll state of the stream. Wrap it around the `MessageScroller`
 * and any control that reads or changes the scroll, such as a composer.
 */
function MessageScrollerProvider({ children }: MessageScrollerProviderProps) {
  const [viewport, setViewport] = React.useState<HTMLDivElement | null>(null);
  const [content, setContent] = React.useState<HTMLDivElement | null>(null);
  const pinnedRef = React.useRef(true);
  // Set while `scrollToStart` animates away from the end, whose first frames
  // are still near enough to the end to re-pin.
  const leavingEndRef = React.useRef(false);

  const [isScrollable, setIsScrollable] = React.useState(false);
  const [isAtEnd, setIsAtEnd] = React.useState(true);
  const [isAtStart, setIsAtStart] = React.useState(true);

  React.useEffect(() => {
    if (!viewport || !content) return;

    let lastScrollTop = 0;

    const isNearEnd = () =>
      viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight <=
      EDGE_THRESHOLD;

    const measure = () => {
      lastScrollTop = viewport.scrollTop;
      setIsAtEnd(isNearEnd());
      setIsAtStart(viewport.scrollTop <= EDGE_THRESHOLD);
      setIsScrollable(viewport.scrollHeight - viewport.clientHeight > 1);
    };

    // A scroll event can be dispatched after content has already grown, so it
    // would measure the old position against the new height. Only an upward
    // move releases the pin; reaching the end restores it, except while
    // `scrollToStart` is still animating away from the end.
    const handleScroll = () => {
      const { scrollTop } = viewport;
      if (scrollTop < lastScrollTop) pinnedRef.current = false;
      if (scrollTop > lastScrollTop || scrollTop === 0) {
        leavingEndRef.current = false;
      }
      if (isNearEnd() && !leavingEndRef.current) pinnedRef.current = true;
      measure();
    };

    const holdEnd = () => {
      if (pinnedRef.current) viewport.scrollTo({ top: viewport.scrollHeight });
      measure();
    };

    const observer = new ResizeObserver(holdEnd);

    pinnedRef.current = true;
    viewport.scrollTo({ top: viewport.scrollHeight });
    measure();
    viewport.addEventListener('scroll', handleScroll, { passive: true });
    observer.observe(content);
    observer.observe(viewport);

    return () => {
      viewport.removeEventListener('scroll', handleScroll);
      observer.disconnect();
    };
  }, [viewport, content]);

  // Pinning first lets the resize observer carry the scroll the rest of the
  // way when content grows mid-animation.
  const scrollToEnd = React.useCallback(() => {
    if (!viewport) return;
    pinnedRef.current = true;
    leavingEndRef.current = false;
    smoothScrollTo(viewport, viewport.scrollHeight);
  }, [viewport]);

  const scrollToStart = React.useCallback(() => {
    // Already at the start, no scroll event would follow to clear the flag.
    if (!viewport || viewport.scrollTop === 0) return;
    pinnedRef.current = false;
    leavingEndRef.current = true;
    smoothScrollTo(viewport, 0);
  }, [viewport]);

  const value = React.useMemo(
    () => ({ isScrollable, isAtEnd, isAtStart, scrollToEnd, scrollToStart }),
    [isScrollable, isAtEnd, isAtStart, scrollToEnd, scrollToStart]
  );

  const nodes = React.useMemo(() => ({ setViewport, setContent }), []);

  return (
    <MessageScrollerContext.Provider value={value}>
      <MessageScrollerNodesContext.Provider value={nodes}>
        {children}
      </MessageScrollerNodesContext.Provider>
    </MessageScrollerContext.Provider>
  );
}

/**
 * Props for the MessageScroller component.
 */
type MessageScrollerProps = React.ComponentProps<
  typeof ScrollAreaPrimitive.Root
>;

/**
 * Scroll container that keeps the latest turn in view until the reader
 * scrolls up. To announce new turns, set `announce` on `MessageGroup`.
 */
function MessageScroller({
  className,
  children,
  ...props
}: MessageScrollerProps) {
  const { isAtStart, isAtEnd } = useMessageScroller();

  return (
    <ScrollAreaPrimitive.Root
      data-slot="message-scroller"
      data-at-start={isAtStart}
      data-at-end={isAtEnd}
      className={cn(
        'nx:relative nx:flex nx:min-h-0 nx:w-full nx:flex-col nx:overflow-hidden',
        className
      )}
      {...props}
    >
      {children}
      <ScrollBar />
      <ScrollAreaPrimitive.Corner data-slot="message-scroller-corner" />
    </ScrollAreaPrimitive.Root>
  );
}

/**
 * Props for the MessageScrollerViewport component.
 */
type MessageScrollerViewportProps = React.ComponentProps<
  typeof ScrollAreaPrimitive.Viewport
>;

/**
 * Scrolling region of the stream, focusable so keyboard users can scroll it.
 * Scrolling past its end does not scroll the page behind it.
 */
function MessageScrollerViewport({
  className,
  ref,
  ...props
}: MessageScrollerViewportProps) {
  const { isAtStart, isAtEnd } = useMessageScroller();
  const { setViewport } = useMessageScrollerNodes();
  const composedRef = useComposedRefs(ref, setViewport);

  return (
    <ScrollAreaPrimitive.Viewport
      ref={composedRef}
      data-slot="message-scroller-viewport"
      tabIndex={0}
      className={cn(
        'nx:size-full nx:min-h-0 nx:min-w-0 nx:overscroll-contain nx:rounded-[inherit] nx:*:h-full nx:focus-visible:outline-2 nx:focus-visible:outline-focus-default',
        !isAtStart && 'nx:mask-t-from-90%',
        !isAtEnd && 'nx:mask-b-from-90%',
        className
      )}
      {...props}
    />
  );
}

/**
 * Props for the MessageScrollerContent component.
 */
type MessageScrollerContentProps = React.ComponentProps<'div'>;

/**
 * Column of turns inside the viewport. A short stream starts at the top.
 */
function MessageScrollerContent({
  className,
  ref,
  ...props
}: MessageScrollerContentProps) {
  const { setContent } = useMessageScrollerNodes();
  const composedRef = useComposedRefs(ref, setContent);

  return (
    <div
      ref={composedRef}
      data-slot="message-scroller-content"
      className={cn(
        'nx:flex nx:h-max nx:min-h-full nx:flex-col nx:gap-6 nx:p-4',
        className
      )}
      {...props}
    />
  );
}

/**
 * Props for the MessageScrollerItem component.
 */
type MessageScrollerItemProps = React.ComponentProps<'div'>;

/**
 * One entry in the stream. Wrap each turn in one so it never shrinks.
 */
function MessageScrollerItem({
  className,
  ...props
}: MessageScrollerItemProps) {
  return (
    <div
      data-slot="message-scroller-item"
      className={cn('nx:min-w-0 nx:shrink-0', className)}
      {...props}
    />
  );
}

const messageScrollerButtonVariants = cva(
  'nx:absolute nx:inset-x-0 nx:z-sticky nx:mx-auto nx:rounded-full nx:[&_svg]:size-4 nx:data-[active=false]:invisible',
  {
    variants: {
      direction: {
        start: 'nx:top-4',
        end: 'nx:bottom-4',
      },
    },
    defaultVariants: {
      direction: 'end',
    },
  }
);

/**
 * Props for the MessageScrollerButton component.
 */
type MessageScrollerButtonProps = Omit<
  React.ComponentProps<typeof Button>,
  'children' | 'asChild'
> &
  VariantProps<typeof messageScrollerButtonVariants>;

/**
 * Button that jumps to the latest turn, or the oldest with `direction="start"`.
 * It appears once the reader scrolls away from that end.
 */
function MessageScrollerButton({
  className,
  direction = 'end',
  variant = 'outline',
  size = 'icon-sm',
  ...props
}: MessageScrollerButtonProps) {
  const { isScrollable, isAtEnd, isAtStart, scrollToEnd, scrollToStart } =
    useMessageScroller();

  const isActive =
    isScrollable && (direction === 'end' ? !isAtEnd : !isAtStart);

  const Icon = direction === 'end' ? IconArrowDown : IconArrowUp;

  return (
    <Button
      data-slot="message-scroller-button"
      data-direction={direction}
      data-active={isActive}
      aria-label={
        direction === 'end'
          ? 'Scroll to the latest message'
          : 'Scroll to the oldest message'
      }
      variant={variant}
      size={size}
      onClick={direction === 'end' ? scrollToEnd : scrollToStart}
      className={cn(messageScrollerButtonVariants({ direction }), className)}
      {...props}
    >
      <Icon />
    </Button>
  );
}

export {
  MessageScroller,
  MessageScrollerButton,
  type MessageScrollerButtonProps,
  messageScrollerButtonVariants,
  MessageScrollerContent,
  type MessageScrollerContentProps,
  MessageScrollerItem,
  type MessageScrollerItemProps,
  type MessageScrollerProps,
  MessageScrollerProvider,
  type MessageScrollerProviderProps,
  MessageScrollerViewport,
  type MessageScrollerViewportProps,
  useMessageScroller,
};

'use client';

import * as React from 'react';

import { IconCheck, IconChevronDown, IconX } from '../../lib/icons';
import { cn } from '../../lib/utils';
import { Badge } from '../badge/badge';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from '../command/command';
import { Popover, PopoverContent, PopoverTrigger } from '../popover/popover';

interface MultiSelectContextValue {
  open: boolean;
  selectedValues: Set<string>;
  labels: Map<string, React.ReactNode>;
  toggle: (value: string) => void;
}

const MultiSelectContext = React.createContext<MultiSelectContextValue | null>(
  null
);

function useMultiSelect() {
  const context = React.useContext(MultiSelectContext);

  if (!context)
    throw new Error('MultiSelect parts must be used inside <MultiSelect>.');

  return context;
}

function toggleValue(values: Set<string>, value: string) {
  const next = new Set(values);

  // Set.delete returns true when the value was present (and removes it), so a
  // failed delete means it wasn't selected — add it instead.
  if (!next.delete(value)) next.add(value);

  return next;
}

/**
 * Walk the composed children and map each option's `value` to the label the
 * trigger chip should show — `badgeLabel`, falling back to the option content.
 */
function collectLabels(
  children: React.ReactNode,
  labels: Map<string, React.ReactNode> = new Map()
) {
  React.Children.forEach(children, (child) => {
    if (!React.isValidElement(child)) return;

    if (child.type === MultiSelectItem) {
      const {
        value,
        badgeLabel,
        children: content,
      } = child.props as MultiSelectItemProps;
      labels.set(value, badgeLabel ?? content);

      return;
    }

    // Recurse through groups, fragments, and any wrapper that carries options
    // as children (e.g. MultiSelectGroup).
    const { children: nested } = child.props as {
      children?: React.ReactNode;
    };
    if (nested) collectLabels(nested, labels);
  });

  return labels;
}

function debounce<T extends (...args: never[]) => void>(func: T, wait: number) {
  let timeout: ReturnType<typeof setTimeout> | null = null;

  return (...args: Parameters<T>) => {
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  };
}

interface MultiSelectProps {
  children: React.ReactNode;
  /**
   * Controlled selected values.
   */
  values?: string[];
  /**
   * Initial selected values for uncontrolled usage.
   */
  defaultValues?: string[];
  /**
   * Called with the new selected values when the selection changes.
   */
  onValuesChange?: (values: string[]) => void;
}

/**
 * Searchable field for picking several options, shown as chips. For
 * searchable single selection, use `Combobox`.
 */
function MultiSelect({
  children,
  values,
  defaultValues,
  onValuesChange,
}: MultiSelectProps) {
  const [open, setOpen] = React.useState(false);
  const [uncontrolled, setUncontrolled] = React.useState(
    () => new Set(values ?? defaultValues)
  );

  const selectedValues = React.useMemo(
    () => (values ? new Set(values) : uncontrolled),
    [values, uncontrolled]
  );

  const labels = React.useMemo(() => collectLabels(children), [children]);

  const toggle = React.useCallback(
    (value: string) => {
      const nextValues = toggleValue(selectedValues, value);

      if (values === undefined) setUncontrolled(nextValues);
      onValuesChange?.([...nextValues]);
    },
    [selectedValues, values, onValuesChange]
  );

  const context = React.useMemo<MultiSelectContextValue>(
    () => ({ open, selectedValues, labels, toggle }),
    [open, selectedValues, labels, toggle]
  );

  return (
    <MultiSelectContext.Provider value={context}>
      <Popover open={open} onOpenChange={setOpen}>
        {children}
      </Popover>
    </MultiSelectContext.Provider>
  );
}

type MultiSelectTriggerProps = React.ComponentProps<'button'>;

/**
 * Field that shows the selected values, opens the list, and removes the last
 * value on Backspace or Delete. Needs an `aria-label` or a visible label from
 * `Field`.
 */
function MultiSelectTrigger({
  className,
  children,
  ...props
}: MultiSelectTriggerProps) {
  const { open, selectedValues, toggle } = useMultiSelect();

  const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (event.key !== 'Backspace' && event.key !== 'Delete') return;

    const values = [...selectedValues];
    const last = values[values.length - 1];
    if (last !== undefined) toggle(last);
  };

  return (
    <PopoverTrigger asChild>
      <button
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        data-slot="multi-select-trigger"
        className={cn(
          'nx:group/multi-select nx:flex nx:h-auto nx:min-h-10 nx:w-full nx:items-center nx:justify-between nx:gap-2 nx:rounded-md nx:border-default nx:border-border-default nx:bg-container nx:text-inherit nx:px-3 nx:py-1.5 nx:typography-body-default nx:whitespace-nowrap nx:transition-field',
          'nx:enabled:hover:bg-container-hover',
          'nx:focus-visible:outline-default nx:focus-visible:outline-focus-default nx:focus-visible:border-focus-default',
          'nx:aria-invalid:border-error-border nx:aria-invalid:focus-visible:outline-focus-error nx:aria-invalid:focus-visible:border-focus-error',
          'nx:disabled:cursor-not-allowed nx:disabled:border-border-disabled nx:disabled:bg-disabled nx:disabled:text-disabled-foreground',
          className
        )}
        onKeyDown={handleKeyDown}
        {...props}
      >
        {children}
        <IconChevronDown
          aria-hidden="true"
          className="nx:size-4 nx:shrink-0 nx:text-muted-foreground nx:group-disabled/multi-select:text-disabled-foreground"
        />
      </button>
    </PopoverTrigger>
  );
}

interface MultiSelectValueProps extends Omit<
  React.ComponentProps<'div'>,
  'children'
> {
  /**
   * Shown when nothing is selected.
   */
  placeholder?: React.ReactNode;
  /**
   * Shows each selected value as a removable chip.
   */
  clickToRemove?: boolean;
  /**
   * What chips do when they overflow the field:
   * - `wrap`: wrap onto more lines.
   * - `wrap-when-open`: wrap while the list is open, show `+N` when closed.
   * - `cutoff`: always show the extra chips as a `+N` badge.
   */
  overflowBehavior?: 'wrap' | 'wrap-when-open' | 'cutoff';
}

/**
 * Selected values inside the trigger, shown as removable chips. Chips that
 * don't fit become a `+N` badge unless they wrap.
 */
function MultiSelectValue({
  className,
  placeholder = 'Select options',
  clickToRemove = true,
  overflowBehavior = 'wrap-when-open',
  ...props
}: MultiSelectValueProps) {
  const { selectedValues, labels, open, toggle } = useMultiSelect();
  const [overflowAmount, setOverflowAmount] = React.useState(0);
  const valueRef = React.useRef<HTMLDivElement>(null);

  const shouldWrap =
    overflowBehavior === 'wrap' ||
    (overflowBehavior === 'wrap-when-open' && open);

  const checkOverflow = React.useCallback(() => {
    const container = valueRef.current;

    if (!container) return;

    const chips = container.querySelectorAll<HTMLElement>(
      '[data-selected-item]'
    );

    // Reset to the fully-expanded state, then hide chips from the end until the
    // row stops overflowing — the count of hidden chips becomes the `+N` badge,
    // whose visibility is driven from that count in render (single source).
    chips.forEach((chip) => chip.style.removeProperty('display'));

    let amount = 0;

    for (let i = chips.length - 1; i >= 0; i--) {
      const chip = chips[i];

      if (!chip) continue;
      if (container.scrollWidth <= container.clientWidth) break;

      amount = chips.length - i;
      chip.style.display = 'none';
    }

    setOverflowAmount(amount);
  }, []);

  const handleResize = React.useCallback(
    (node: HTMLDivElement) => {
      valueRef.current = node;

      const mutationObserver = new MutationObserver(checkOverflow);
      const resizeObserver = new ResizeObserver(debounce(checkOverflow, 100));

      mutationObserver.observe(node, {
        childList: true,
        attributes: true,
        attributeFilter: ['class', 'style'],
      });
      resizeObserver.observe(node);

      return () => {
        mutationObserver.disconnect();
        resizeObserver.disconnect();
        valueRef.current = null;
      };
    },
    [checkOverflow]
  );

  if (selectedValues.size === 0)
    return (
      <span
        data-slot="multi-select-placeholder"
        className="nx:truncate nx:text-muted-foreground"
      >
        {placeholder}
      </span>
    );

  const removeChip = (event: React.MouseEvent, value: string) => {
    event.stopPropagation();
    toggle(value);
  };

  const isChipHidden = shouldWrap || overflowAmount === 0;

  return (
    <div
      data-slot="multi-select-value"
      ref={handleResize}
      className={cn(
        'nx:flex nx:min-w-0 nx:flex-1 nx:items-center nx:gap-1.5 nx:overflow-hidden',
        shouldWrap && 'nx:h-full nx:flex-wrap',
        className
      )}
      {...props}
    >
      {[...selectedValues].map((value) => (
        <Badge
          key={value}
          data-slot="multi-select-chip"
          data-selected-item
          variant="secondary"
          fill="outline"
          isCaps={false}
          className={cn(
            'nx:group/chip nx:max-w-40 nx:gap-1',
            clickToRemove && 'nx:cursor-pointer'
          )}
          onClick={
            clickToRemove ? (event) => removeChip(event, value) : undefined
          }
        >
          <span className="nx:truncate">{labels.get(value) ?? value}</span>
          {clickToRemove && (
            <IconX
              aria-hidden="true"
              className="nx:size-3 nx:text-muted-foreground nx:transition-colors nx:group-hover/chip:text-error-subtle-foreground"
            />
          )}
        </Badge>
      ))}
      <Badge
        data-slot="multi-select-overflow"
        variant="secondary"
        fill="light"
        isCaps={false}
        style={{ display: isChipHidden ? 'none' : undefined }}
      >
        +{overflowAmount}
      </Badge>
    </div>
  );
}

interface MultiSelectContentProps extends Omit<
  React.ComponentProps<typeof PopoverContent>,
  'children'
> {
  children: React.ReactNode;
  /**
   * Placeholder for the search input.
   */
  searchPlaceholder?: string;
  /**
   * Shown when the search matches no options.
   */
  emptyMessage?: React.ReactNode;
}

/**
 * Searchable list of options, shown in a popover.
 */
function MultiSelectContent({
  children,
  className,
  align = 'start',
  sideOffset = 6,
  searchPlaceholder = 'Search…',
  emptyMessage = 'No results found.',
  ...props
}: MultiSelectContentProps) {
  return (
    <PopoverContent
      data-slot="multi-select-content"
      aria-label="Options"
      align={align}
      sideOffset={sideOffset}
      className={cn(
        'nx:w-(--radix-popover-trigger-width) nx:min-w-56 nx:p-0',
        className
      )}
      {...props}
    >
      <Command>
        <CommandInput placeholder={searchPlaceholder} />
        <CommandList>
          <CommandEmpty>{emptyMessage}</CommandEmpty>
          {children}
        </CommandList>
      </Command>
    </PopoverContent>
  );
}

interface MultiSelectItemProps extends Omit<
  React.ComponentProps<typeof CommandItem>,
  'value' | 'onSelect'
> {
  value: string;
  /**
   * Chip text when it differs from the option content, such as an icon option.
   */
  badgeLabel?: React.ReactNode;
  /**
   * Called with the option's value after it is toggled.
   */
  onSelect?: (value: string) => void;
}

/**
 * Option with a checkbox, found by its `value`, `keywords` or plain-text
 * label. Give each option a unique `value`.
 */
function MultiSelectItem({
  value,
  children,
  badgeLabel,
  keywords,
  onSelect,
  className,
  ...props
}: MultiSelectItemProps) {
  // MultiSelect reads `badgeLabel` from its children; it isn't a DOM prop.
  void badgeLabel;
  const { selectedValues, toggle } = useMultiSelect();
  const selected = selectedValues.has(value);

  const handleSelect = () => {
    toggle(value);
    onSelect?.(value);
  };

  const searchKeywords =
    keywords ?? (typeof children === 'string' ? [children] : undefined);

  return (
    <CommandItem
      data-slot="multi-select-item"
      data-checked={selected || undefined}
      value={value}
      keywords={searchKeywords}
      className={cn('nx:gap-2', className)}
      onSelect={handleSelect}
      {...props}
    >
      <span
        aria-hidden="true"
        data-slot="multi-select-indicator"
        className={cn(
          'nx:flex nx:size-4 nx:shrink-0 nx:items-center nx:justify-center nx:rounded-sm nx:border-default nx:transition-colors',
          selected
            ? 'nx:border-transparent nx:bg-primary-background nx:text-primary-foreground'
            : 'nx:border-border-default nx:bg-background'
        )}
      >
        {selected && <IconCheck className="nx:size-3" />}
      </span>
      <span className="nx:min-w-0 nx:flex-1">{children}</span>
    </CommandItem>
  );
}

type MultiSelectGroupProps = React.ComponentProps<typeof CommandGroup>;

/**
 * Groups related options under an optional `heading`.
 */
function MultiSelectGroup(props: MultiSelectGroupProps) {
  return <CommandGroup data-slot="multi-select-group" {...props} />;
}

type MultiSelectSeparatorProps = React.ComponentProps<typeof CommandSeparator>;

/**
 * Divider between groups or options.
 */
function MultiSelectSeparator(props: MultiSelectSeparatorProps) {
  return <CommandSeparator data-slot="multi-select-separator" {...props} />;
}

