import {
  type ResponsiveVisibilityProps,
  visibilityClassName,
} from '../../lib/responsive-visibility';
import { cn } from '../../lib/utils';

/**
 * Shows its children only while a width condition matches. Children stay
 * mounted, and only their CSS `display` changes.
 *
 * Set exactly one of these props:
 * - `above` / `below`: viewport min or max width (`sm` 40rem to `2xl` 96rem).
 * - `containerAbove` / `containerBelow`: min or max width of the nearest
 *   container (`sm` 24rem to `2xl` 42rem).
 *
 * Container props need an unnamed container ancestor, such as a parent with
 * `nx:@container`. For a named container, use `nx:@container/{name}/{bp}:`
 * utilities.
 *
 * @experimental Inferred from Atlassian's `<Show>` / `<Hide>`; the API may change before stable.
 */
function Show({
  as: Comp = 'span',
  className,
  children,
  above,
  below,
  containerAbove,
  containerBelow,
  ...props
}: ResponsiveVisibilityProps) {
  return (
    <Comp
      data-slot="show"
      className={cn(
        className,
        visibilityClassName(
          { above, below, containerAbove, containerBelow },
          false
        )
      )}
      {...props}
    >
      {children}
    </Comp>
  );
}

export { Show, type ResponsiveVisibilityProps as ShowProps };

/**
 * Shared internals for the `<Show>` / `<Hide>` responsive-visibility primitives.
 *
 * Visibility toggles between `display: contents` (shown) and `display: none`
 * (hidden) — never `display: block` / `revert`. A `contents` wrapper generates
 * no box of its own, so its children keep their natural flow: inline stays
 * inline, flex/grid children stay flex/grid items. Forcing `block` (or reverting
 * to the element's UA default) would override the wrapper's display and break
 * those layouts.
 *
 * Class strings are full static literals in the maps below: Tailwind only emits
 * a utility it can see as a complete string, so a computed `nx:${bp}:contents`
 * would never ship in the CSS bundle.
 *
 * Container axes use Tailwind's native `@container` scale (`@md` = 28rem), which
 * is smaller than the viewport scale (`md` = 48rem) — a component
 * reads as "md" at a narrower width than the whole viewport. The two axes
 * therefore resolve the same breakpoint name to different rem values.
 */

import type { HTMLAttributes, ReactNode } from 'react';

export type Breakpoint = 'sm' | 'md' | 'lg' | 'xl' | '2xl';

/**
 * Exactly one axis must be provided. The `never` siblings make the four axes
 * mutually exclusive at compile time (zero or two+ axes fail to typecheck).
 */
export type VisibilityAxis =
  | {
      above: Breakpoint;
      below?: never;
      containerAbove?: never;
      containerBelow?: never;
    }
  | {
      above?: never;
      below: Breakpoint;
      containerAbove?: never;
      containerBelow?: never;
    }
  | {
      above?: never;
      below?: never;
      containerAbove: Breakpoint;
      containerBelow?: never;
    }
  | {
      above?: never;
      below?: never;
      containerAbove?: never;
      containerBelow: Breakpoint;
    };

export type ResponsiveVisibilityProps = HTMLAttributes<HTMLElement> & {
  /**
   * Wrapper tag: `span` (inline) or `div` (block) — match the child's layout.
   * Tag-only and non-semantic: `display: contents` can
   * drop a semantic element's box from the accessibility tree, so put semantics
   * on a child *inside* `<Show>` / `<Hide>` instead.
   */
  as?: 'span' | 'div';
  children: ReactNode;
} & VisibilityAxis;

/** Loose shape the resolver works with; the strict union is enforced at the prop boundary. */
type AxisValues = {
  above?: Breakpoint;
  below?: Breakpoint;
  containerAbove?: Breakpoint;
  containerBelow?: Breakpoint;
};

// Shown = `contents`, hidden = `none`. Keyed by breakpoint; each value is a
// complete, statically-scannable class string (see header for why).
const VIEWPORT_ABOVE: Record<Breakpoint, string> = {
  sm: 'nx:hidden nx:sm:contents',
  md: 'nx:hidden nx:md:contents',
  lg: 'nx:hidden nx:lg:contents',
  xl: 'nx:hidden nx:xl:contents',
  '2xl': 'nx:hidden nx:2xl:contents',
};

const VIEWPORT_BELOW: Record<Breakpoint, string> = {
  sm: 'nx:contents nx:sm:hidden',
  md: 'nx:contents nx:md:hidden',
  lg: 'nx:contents nx:lg:hidden',
  xl: 'nx:contents nx:xl:hidden',
  '2xl': 'nx:contents nx:2xl:hidden',
};

const CONTAINER_ABOVE: Record<Breakpoint, string> = {
  sm: 'nx:hidden nx:@sm:contents',
  md: 'nx:hidden nx:@md:contents',
  lg: 'nx:hidden nx:@lg:contents',
  xl: 'nx:hidden nx:@xl:contents',
  '2xl': 'nx:hidden nx:@2xl:contents',
};

const CONTAINER_BELOW: Record<Breakpoint, string> = {
  sm: 'nx:contents nx:@sm:hidden',
  md: 'nx:contents nx:@md:hidden',
  lg: 'nx:contents nx:@lg:hidden',
  xl: 'nx:contents nx:@xl:hidden',
  '2xl': 'nx:contents nx:@2xl:hidden',
};

/**
 * Resolve the visibility class string for the one provided axis. `invert` swaps
 * show/hide so `<Hide>` is `<Show>` with the maps flipped (hide-above === show-below).
 */
export function visibilityClassName(
  { above, below, containerAbove, containerBelow }: AxisValues,
  invert: boolean
): string {
  if (above) return (invert ? VIEWPORT_BELOW : VIEWPORT_ABOVE)[above];
  if (below) return (invert ? VIEWPORT_ABOVE : VIEWPORT_BELOW)[below];
  if (containerAbove)
    return (invert ? CONTAINER_BELOW : CONTAINER_ABOVE)[containerAbove];
  if (containerBelow)
    return (invert ? CONTAINER_ABOVE : CONTAINER_BELOW)[containerBelow];
  // unreachable — the props union guarantees exactly one axis
  return '';
}

'use client';

import * as React from 'react';

import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';

import { useIsNarrow } from '../../hooks/use-narrow';
import { IconLayoutSidebar } from '../../lib/icons';
import { cn } from '../../lib/utils';
import { Button } from '../button/button';
import { Input } from '../input/input';
import { Separator } from '../separator/separator';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '../sheet/sheet';
import { Skeleton } from '../skeleton/skeleton';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '../tooltip/tooltip';

const SIDEBAR_COOKIE_NAME = 'sidebar_state';
const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7;
const SIDEBAR_WIDTH = '16rem';
const SIDEBAR_WIDTH_NARROW = '18rem';
const SIDEBAR_WIDTH_ICON = '3rem';
const SIDEBAR_KEYBOARD_SHORTCUT = 'b';

/** Whether the event target is a text-entry element (input, textarea, or contenteditable). */
function isEditableTarget(target: EventTarget | null) {
  if (!(target instanceof HTMLElement)) return false;
  return (
    target.isContentEditable ||
    target.tagName === 'INPUT' ||
    target.tagName === 'TEXTAREA'
  );
}

/**
 * Shape of the context shared by `SidebarProvider` with every sidebar part.
 */
interface SidebarContextProps {
  state: 'expanded' | 'collapsed';
  open: boolean;
  setOpen: (value: boolean | ((value: boolean) => boolean)) => void;
  openNarrow: boolean;
  setOpenNarrow: (open: boolean) => void;
  isNarrow: boolean;
  toggleSidebar: () => void;
}

const SidebarContext = React.createContext<SidebarContextProps | null>(null);

/**
 * Reads the sidebar state and the `toggleSidebar` helper. Call it inside a
 * `SidebarProvider`, or it throws.
 */
function useSidebar() {
  const context = React.useContext(SidebarContext);
  if (!context) {
    throw new Error('useSidebar must be used within a SidebarProvider.');
  }

  return context;
}

/**
 * Props for SidebarProvider.
 */
interface SidebarProviderProps extends React.ComponentProps<'div'> {
  /**
   * Opens the sidebar on first render when uncontrolled. The open state is saved
   * to a `sidebar_state` cookie. Read that cookie on the server and pass it here
   * to restore it.
   */
  defaultOpen?: boolean;
  /**
   * Controlled open state. Pair it with `onOpenChange`.
   */
  open?: boolean;
  /**
   * Called when the open state changes in controlled mode.
   */
  onOpenChange?: (open: boolean) => void;
}

/**
 * Holds the open state and the `Ctrl/Cmd+B` shortcut. Wrap your app shell in
 * it. It includes a `TooltipProvider` for collapsed-icon tooltips.
 */
function SidebarProvider({
  defaultOpen = true,
  open: openProp,
  onOpenChange: setOpenProp,
  className,
  style,
  children,
  ...props
}: SidebarProviderProps) {
  const isNarrow = useIsNarrow();
  const [openNarrow, setOpenNarrow] = React.useState(false);

  // Internal open state; openProp/setOpenProp take over when controlled.
  const [_open, _setOpen] = React.useState(defaultOpen);
  const open = openProp ?? _open;
  const setOpen = React.useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState = typeof value === 'function' ? value(open) : value;
      if (setOpenProp) {
        setOpenProp(openState);
        return;
      }

      _setOpen(openState);
      // Persist non-sensitive uncontrolled open state for server-side restore.
      document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}; SameSite=Lax`;
    },
    [setOpenProp, open]
  );

  const toggleSidebar = React.useCallback(() => {
    return isNarrow
      ? setOpenNarrow((value) => !value)
      : setOpen((value) => !value);
  }, [isNarrow, setOpen, setOpenNarrow]);

  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== SIDEBAR_KEYBOARD_SHORTCUT) return;
      if (!event.metaKey && !event.ctrlKey) return;
      // Don't hijack Cmd/Ctrl+B (native bold) while typing in an editor.
      if (isEditableTarget(event.target)) return;

      event.preventDefault();
      toggleSidebar();
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [toggleSidebar]);

  // Drives data-state="expanded" | "collapsed" for the styling hooks below.
  const state = open ? 'expanded' : 'collapsed';

  const contextValue = React.useMemo<SidebarContextProps>(
    () => ({
      state,
      open,
      setOpen,
      isNarrow,
      openNarrow,
      setOpenNarrow,
      toggleSidebar,
    }),
    [state, open, setOpen, isNarrow, openNarrow, setOpenNarrow, toggleSidebar]
  );

  return (
    <SidebarContext.Provider value={contextValue}>
      <TooltipProvider delayDuration={0}>
        <div
          data-slot="sidebar-wrapper"
          style={
            {
              '--sidebar-width': SIDEBAR_WIDTH,
              '--sidebar-width-icon': SIDEBAR_WIDTH_ICON,
              ...style,
            } as React.CSSProperties
          }
          className={cn(
            'nx:group/sidebar-wrapper nx:flex nx:min-h-svh nx:w-full nx:has-data-[variant=inset]:bg-nav-background',
            className
          )}
          {...props}
        >
          {children}
        </div>
      </TooltipProvider>
    </SidebarContext.Provider>
  );
}

/**
 * Props for Sidebar.
 */
interface SidebarProps extends React.ComponentProps<'div'> {
  /**
   * Edge the sidebar docks to.
   */
  side?: 'left' | 'right';
  /**
   * Visual style. `inset` pairs with `SidebarInset` to show the main region as a
   * card.
   */
  variant?: 'sidebar' | 'floating' | 'inset';
  /**
   * How it collapses: slides off screen, shrinks to an icon rail, or never.
   */
  collapsible?: 'offcanvas' | 'icon' | 'none';
}

/**
 * The sidebar panel. Below `md` it opens as a Sheet. From `md` up it docks to
 * `side` and collapses as `collapsible` sets.
 */
function Sidebar({
  side = 'left',
  variant = 'sidebar',
  collapsible = 'offcanvas',
  className,
  style,
  children,
  ...props
}: SidebarProps) {
  const { isNarrow, state, openNarrow, setOpenNarrow } = useSidebar();

  if (collapsible === 'none') {
    return (
      <div
        data-slot="sidebar"
        className={cn(
          'nx:flex nx:h-full nx:w-(--sidebar-width) nx:flex-col nx:bg-nav-background nx:text-nav-foreground',
          className
        )}
        style={style}
        {...props}
      >
        {children}
      </div>
    );
  }

  if (isNarrow) {
    return (
      <Sheet open={openNarrow} onOpenChange={setOpenNarrow}>
        <SheetContent
          data-slot="sidebar"
          data-narrow="true"
          side={side}
          className={cn(
            'nx:inset-y-2 nx:h-auto nx:w-(--sidebar-width) nx:max-w-[calc(100vw-1rem)] nx:rounded-lg nx:border-default nx:border-nav-border nx:bg-nav-background nx:p-0 nx:text-nav-foreground',
            side === 'left'
              ? 'nx:left-2 nx:data-[state=closed]:-translate-x-[calc(100%+0.5rem)]'
              : 'nx:right-2 nx:data-[state=closed]:translate-x-[calc(100%+0.5rem)]',
            className
          )}
          style={
            {
              '--sidebar-width': SIDEBAR_WIDTH_NARROW,
              ...style,
            } as React.CSSProperties
          }
          {...props}
        >
          <SheetHeader className="nx:sr-only">
            <SheetTitle>Sidebar</SheetTitle>
            <SheetDescription>
              Displays the narrow-tier sidebar.
            </SheetDescription>
          </SheetHeader>
          <div className="nx:flex nx:h-full nx:w-full nx:flex-col">
            {children}
          </div>
        </SheetContent>
      </Sheet>
    );
  }

  return (
    <div
      className="nx:group nx:peer nx:hidden nx:text-nav-foreground nx:md:block"
      data-state={state}
      data-collapsible={state === 'collapsed' ? collapsible : ''}
      data-variant={variant}
      data-side={side}
      data-slot="sidebar"
    >
      {/* Handles the sidebar gap on desktop. */}
      <div
        data-slot="sidebar-gap"
        className={cn(
          'nx:relative nx:w-(--sidebar-width) nx:bg-transparent nx:transition-[width] nx:duration-default nx:ease-linear',
          'nx:group-data-[collapsible=offcanvas]:w-0',
          'nx:group-data-[side=right]:rotate-180',
          variant === 'floating' || variant === 'inset'
            ? 'nx:group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+1rem)]'
            : 'nx:group-data-[collapsible=icon]:w-(--sidebar-width-icon)'
        )}
      />
      <div
        data-slot="sidebar-container"
        className={cn(
          'nx:fixed nx:inset-y-0 nx:z-sticky nx:hidden nx:h-svh nx:w-(--sidebar-width) nx:transition-[left,right,width] nx:duration-default nx:ease-linear nx:md:flex',
          side === 'left'
            ? 'nx:left-0 nx:group-data-[collapsible=offcanvas]:-left-(--sidebar-width)'
            : 'nx:right-0 nx:group-data-[collapsible=offcanvas]:-right-(--sidebar-width)',
          // Floating and inset variants gain padding around the panel; the
          // +1rem in the icon-collapse width below matches this inset.
          (variant === 'floating' || variant === 'inset') && 'nx:p-2',
          variant === 'floating' || variant === 'inset'
            ? 'nx:group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+1rem+2px)]'
            : 'nx:group-data-[collapsible=icon]:w-(--sidebar-width-icon) nx:group-data-[side=left]:border-r-default nx:group-data-[side=right]:border-l-default nx:border-nav-border',
          className
        )}
        style={style}
        {...props}
      >
        <div
          data-slot="sidebar-inner"
          className="nx:flex nx:h-full nx:w-full nx:flex-col nx:bg-nav-background nx:group-data-[variant=floating]:rounded-lg nx:group-data-[variant=floating]:border-default nx:group-data-[variant=floating]:border-nav-border nx:group-data-[variant=floating]:shadow-sm"
        >
          {children}
        </div>
      </div>
    </div>
  );
}

