type TableCellProps = React.ComponentProps<'td'>;

const tableCellVariants = cva('nx:px-2 nx:align-middle nx:whitespace-nowrap', {
  variants: {
    variant: {
      default: '',
      borderless: '',
      grid: 'nx:border-e-default nx:border-border-default-alpha nx:last:border-e-0',
