/**
 * Edits one line of text in place. Your app owns the saved value, saving and
 * any error. `editing` and `onEditingChange` control when the editor is open.
 */
export function InlineEdit({
  value,
  label,
  onCommit,
  editing: editingProp,
  onEditingChange,
  readOnly = false,
  error,
  activation = 'pencil',
  blurBehavior = 'keep-open',
  required = false,
  requiredMessage = `${label} is required.`,
  emptyText = 'Not provided',
  placeholder,
  className,
  ...props
}: InlineEditProps) {
  const [uncontrolledEditing, setUncontrolledEditing] = React.useState(false);
  const editing = !readOnly && (editingProp ?? uncontrolledEditing);
  const trigger = React.useRef<HTMLButtonElement>(null);
  const Trigger =
    activation === 'click' ? InlineEditClickTrigger : InlineEditPencilTrigger;
  const display = <InlineEditValue value={value} emptyText={emptyText} />;

  function setEditing(next: boolean) {
    if (editingProp === undefined) setUncontrolledEditing(next);
    onEditingChange?.(next);
  }

  return (
    <div
      data-slot="inline-edit"
      data-activation={activation}
      data-editing={editing || undefined}
      data-readonly={readOnly || undefined}
      className={cn('nx:min-w-0 nx:typography-body-default', className)}
      {...props}
    >
      {readOnly && display}
      {editing && (
        <InlineEditEditor
          value={value}
          label={label}
          error={error}
          blurBehavior={blurBehavior}
          required={required}
          requiredMessage={requiredMessage}
          placeholder={placeholder}
          onCommit={onCommit}
          onClose={() => setEditing(false)}
          trigger={trigger}
        />
      )}
      {!readOnly && !editing && (
        <Trigger ref={trigger} label={label} onClick={() => setEditing(true)}>
          {display}
        </Trigger>
      )}
    </div>
  );
}

