              {icon}
              <span className="nx:truncate">{label}</span>
            </FilterConditionField>
            <ConditionOperator
              triggerRef={operatorRef}
              label={label}
              value={pending ?? value.operator}
              options={['is', 'isNot', 'isEmpty', 'isNotEmpty']}
              onChange={changeOperator}
              disabled={disabled}
              onCloseAutoFocus={openPending}
            />
          </div>
          <div className="nx:inline-flex nx:max-w-full nx:min-w-0 nx:border-s-default nx:border-border-default nx:-ms-(--nx-borderwidth-default)">
            {(applied || pending) && (
              <DropdownMenuTrigger asChild>
                <FilterConditionSegment
                  className="nx:min-w-20"
                  disabled={disabled}
                  aria-label={`Edit ${label}: ${selectedLabel || 'Choose…'}`}
                >
                  {selectedLabel || 'Choose…'}
                </FilterConditionSegment>
              </DropdownMenuTrigger>
            )}
            <FilterConditionRemove
              disabled={disabled}
              aria-label={`Remove ${label} filter`}
              onClick={remove}
            />
          </div>
        </FilterCondition>
      ) : (
        <DropdownMenuTrigger asChild>
          <Button
            ref={focusAdd}
            disabled={disabled}
            variant="outline"
            size="sm"
            className="nx:h-(--nx-spacing-8)"
          >
            Add {label.toLowerCase()} filter
          </Button>
        </DropdownMenuTrigger>
      )}
      <DropdownMenuContent
        aria-label={`Filter by ${label.toLowerCase()}`}
        align="start"
        onCloseAutoFocus={restoreFocus}
      >
        <ChoiceEditor
          label={label}
          value={selected}
          options={options}
          onChange={select}
          disabled={disabled}
        />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/** Controlled option list for DropdownMenuContent. Your `onChange` decides whether it edits a draft or the applied filter. */
export function ChoiceEditor({
  label,
  value,
  options,
  onChange,
  disabled = false,
}: {
  label: string;
  value: string;
  options: readonly ChoiceOption[];
  onChange: (value: string) => void;
  disabled?: boolean;
}) {
  const listed =
    value === '' || options.some((option) => option.value === value)
      ? options
      : [
          ...options,
          { value, label: optionLabel(options, value), disabled: true },
        ];
  function select(next: string) {
    if (disabled) return;
    if (
      next !== '' &&
      !options.some((option) => option.value === next && !option.disabled)
    )
      return;
    onChange(next);
  }
  return (
    <>
      <DropdownMenuRadioGroup
        aria-label={label}
        value={value}
        onValueChange={select}
      >
        <DropdownMenuRadioItem value="" disabled={disabled}>
          Any {label.toLowerCase()}
        </DropdownMenuRadioItem>
        {listed.map((option) => (
          <DropdownMenuRadioItem
            key={option.value}
            value={option.value}
            disabled={disabled || option.disabled}
          >
            {option.label}
          </DropdownMenuRadioItem>
        ))}
      </DropdownMenuRadioGroup>
      {!options.length && (
        <p className="nx:m-0 nx:p-2 nx:typography-body-default nx:text-muted-foreground">
          No options available
        </p>
      )}
    </>
  );
}

